-Cafe/IAM/commit/4f02b001961b967f727a02da9091140a40d596ec","sha":"4f02b001961b967f727a02da9091140a40d596ec","url":"https://api.github.com/repos/A-Digital-Cafe/IAM/commits/4f02b001961b967f727a02da9091140a40d596ec"}],"sha":"c0fcd8f19ff0a6a075adae7dc41e064132ab75e5","url":"https://api.github.com/repos/A-Digital-Cafe/IAM/commits/c0fcd8f19ff0a6a075adae7dc41e064132ab75e5"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/27163541?v=4","events_url":"https://api.github.com/users/abbytec/events{/privacy}","followers_url":"https://api.github.com/users/abbytec/followers","following_url":"https://api.github.com/users/abbytec/following{/other_user}","gists_url":"https://api.github.com/users/abbytec/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/abbytec","id":27163541,"login":"abbytec","node_id":"MDQ6VXNlcjI3MTYzNTQx","organizations_url":"https://api.github.com/users/abbytec/orgs","received_events_url":"https://api.github.com/users/abbytec/received_events","repos_url":"https://api.github.com/users/abbytec/repos","site_admin":false,"starred_url":"https://api.github.com/users/abbytec/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/abbytec/subscriptions","type":"User","url":"https://api.github.com/users/abbytec","user_view_type":"public"},"comments_url":"https://api.github.com/repos/A-Digital-Cafe/IAM/commits/4f02b001961b967f727a02da9091140a40d596ec/comments","commit":{"author":{"date":"2026-08-19T15:28:33Z","email":"gpsmurfs@gmail.com","name":"Abbytec"},"comment_count":0,"committer":{"date":"2026-08-19T15:28:33Z","email":"gpsmurfs@gmail.com","name":"Abbytec"},"message":"feat(identity): resolver roles vigentes por nombre, para el gate de acceso de módulos UI\n\n- IPermissionManager.resolveRoleNames(): nombres de los roles vigentes del usuario en\n  su contexto, espejando exactamente los mismos niveles y predicados que\n  resolvePermissions() (membresía de org, roles directos, roles de grupo) — un rol\n  que aporta permisos tiene que aparecer acá, o el gate de acceso de un módulo UI\n  rechaza a alguien que los endpoints sí autorizan.\n- listAllRoleNames(): catálogo de todos los roles existentes, sólo para que el kernel\n  pueda avisar si un config.json nombra un rol que no existe.\n- SessionManagerService.resolveRoles()/listRoleNames() exponen lo anterior a través de\n  ISessionVerifier, y /api/auth/session ahora incluye user.roles en la respuesta.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"5361b990c4e78d7956b9326fb18af6293f38716e","url":"https://api.github.com/repos/A-Digital-Cafe/IAM/git/trees/5361b990c4e78d7956b9326fb18af6293f38716e"},"url":"https://api.github.com/repos/A-Digital-Cafe/IAM/git/commits/4f02b001961b967f727a02da9091140a40d596ec","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/27163541?v=4","events_url":"https://api.github.com/users/abbytec/events{/privacy}","followers_url":"https://api.github.com/users/abbytec/followers","following_url":"https://api.github.com/users/abbytec/following{/other_user}","gists_url":"https://api.github.com/users/abbytec/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/abbytec","id":27163541,"login":"abbytec","node_id":"MDQ6VXNlcjI3MTYzNTQx","organizations_url":"https://api.github.com/users/abbytec/orgs","received_events_url":"https://api.github.com/users/abbytec/received_events","repos_url":"https://api.github.com/users/abbytec/repos","site_admin":false,"starred_url":"https://api.github.com/users/abbytec/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/abbytec/subscriptions","type":"User","url":"https://api.github.com/users/abbytec","user_view_type":"public"},"html_url":"https://github.com/A-Digital-Cafe/IAM/commit/4f02b001961b967f727a02da9091140a40d596ec","node_id":"C_kwDOT74LXtoAKDRmMDJiMDAxOTYxYjk2N2Y3MjdhMDJkYTkwOTExNDBhNDBkNTk2ZWM","parents":[